statement.tex:
$p$ を素数，$q$ を整数とし，2つの方程式 $x^3+x-p=0$ …①，$x^2+x+q=0$ …② を考える（解は複素数の範囲で考える）．
\begin{enumerate}
  \item ①と②がちょうど1つの共通解をもつような $(p,q)$ を求めよ．
  \item ①と②が2つの共通解をもつような $(p,q)$ を求めよ．
\end{enumerate}

3乗根は実数のものを考える．
\begin{enumerate}
  \item $a=\sqrt[3]{2+\sqrt5}+\sqrt[3]{2-\sqrt5}$ は整数であることを示し，その値を求めよ．
  \item $c=\sqrt[3]{\sqrt2+1}-\sqrt[3]{\sqrt2-1}$ は整数係数の3次方程式の解であることを示し，さらに $c$ は有理数でないことを示せ．
  \item (2) の $c$ について，$c<\dfrac23$ であることを示せ．
\end{enumerate}

\begin{enumerate}
  \item $x^4+ax^2+bx+2$ が $x^2+x+2$ で割り切れるような定数 $a,b$ を求めよ．
  \item $f(x)=x^4+x^3+3x^2+2x+2$ と $g(x)=x^3+4x^2+4x+3$ の最大公約数（最高次の係数を1とする）を，互除法によって求めよ．
\end{enumerate}

$n$ を自然数とし，$x^n$ を $x^2-x-1$ で割った余りを $a_nx+b_n$ とする．
\begin{enumerate}
  \item $a_{n+1},\ b_{n+1}$ を $a_n,\ b_n$ で表せ．
  \item $x^{10}$ を $x^2-x-1$ で割った余りを求めよ．
\end{enumerate}

\begin{enumerate}
  \item $n\geqq3$ のとき，$x^n$ を $(x-1)^3$ で割った余りを $n$ で表せ．
  \item $x^{10}$ を $(x-1)^3$ で割った余りを求めよ．
\end{enumerate}

$f(x)=x^{2026}+x^{1013}+1$ とする．
\begin{enumerate}
  \item $f(x)$ は $x^2+x+1$ で割り切れることを示せ．
  \item $f(x)$ を $x^2-x+1$ で割った余りを求めよ．
\end{enumerate}

\begin{enumerate}
  \item 整式 $P(x)$ を $(x-1)^2$ で割ると余りが $2x+1$，$x+1$ で割ると余りが5である．$P(x)$ を $(x-1)^2(x+1)$ で割った余りを求めよ．
  \item $x^2+1$ で割ると $x+2$ 余り，$x^2+x+1$ で割ると $2x+1$ 余る整式のうち，次数が最も低いものを求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x^4+ax^3+bx^2+12x+9$ がある2次式の2乗になるような $(a,b)$ をすべて求めよ．
  \item $x^2+3xy+2y^2+3x+ky+2$ が $x,y$ の1次式の積に因数分解できるような定数 $k$ をすべて求めよ．
\end{enumerate}

整式 $f(x)$ がすべての実数 $x$ に対して $(x-1)f(x+1)-(x+1)f(x)=-4x-6$ を満たす．
\begin{enumerate}
  \item $f(x)$ の次数は2以下であることを示せ．
  \item このような $f(x)$ をすべて求めよ．また，$f(1)$ の値は $f$ によらず一定であることを示せ．
\end{enumerate}

\begin{enumerate}
  \item $\dfrac{2n^2+5n+9}{2n-1}$ が整数となる自然数 $n$ をすべて求めよ．
  \item $\dfrac{x^2+3}{x-1}$ が整数となる整数 $x$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $a+b+c=0$ のとき，$a^5+b^5+c^5=-5abc(ab+bc+ca)$ であることを示せ．さらに $2(a^5+b^5+c^5)=5abc(a^2+b^2+c^2)$ を示せ．
  \item $x=\dfrac{1+\sqrt5}{2}$ のとき，$x^6-4x^4+2x^3+x^2+3$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\dfrac{x+y}{3}=\dfrac{y+z}{4}=\dfrac{z+x}{5}\neq0$ のとき，$\dfrac{xy+yz+zx}{x^2+y^2+z^2}$ の値を求めよ．
  \item 0でない実数 $a,b,c$ が $\dfrac{b+c}{a}=\dfrac{c+a}{b}=\dfrac{a+b}{c}=k$ を満たす．$k$ の値をすべて求めよ．また，$a,b,c$ が相異なるときの $k$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $a\geqq b\geqq c,\ x\geqq y\geqq z$ のとき，$(a+b+c)(x+y+z)\leqq3(ax+by+cz)$ を示せ．
  \item 三角形の3辺の長さを $a,b,c$，その対角の大きさ（弧度法）を $A,B,C$ とする．$\dfrac{aA+bB+cC}{a+b+c}\geqq\dfrac{\pi}{3}$ を示せ．
\end{enumerate}

\begin{enumerate}
  \item 自然数 $n$ に対して，$2(\sqrt{n+1}-\sqrt n)<\dfrac{1}{\sqrt n}<2(\sqrt n-\sqrt{n-1})$ を示せ．
  \item $S=\displaystyle\sum_{k=1}^{100}\frac{1}{\sqrt k}$ の整数部分を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0,\ y>0$ のとき，$\Bigl(x+\dfrac1y\Bigr)\Bigl(y+\dfrac4x\Bigr)$ の最小値を求めよ．
  \item $x>1$ のとき，$x+\dfrac{4}{x-1}$ の最小値とそのときの $x$ を求めよ．
  \item $a,b,c>0$ のとき，$(a+b)(b+c)(c+a)\geqq8abc$ を示せ．
\end{enumerate}

\begin{enumerate}
  \item 実数 $x,y,z$ が $x+2y+3z=14$ を満たすとき，$x^2+y^2+z^2$ の最小値と，そのときの $x,y,z$ を求めよ．
  \item 正の数 $a,b,c$ が $a+b+c=1$ を満たすとき，$\dfrac1a+\dfrac4b+\dfrac9c$ の最小値と，そのときの $a,b,c$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 実数 $a,b$ が $|a|<1,\ |b|<1$ を満たすとき，$\Bigl|\dfrac{a+b}{1+ab}\Bigr|<1$ を示せ．
  \item 実数 $x,y$ に対して $|x-y|\geqq\bigl||x|-|y|\bigr|$ を示し，等号が成り立つ条件を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\Bigl(\dfrac{1+2i}{2-i}\Bigr)^{10}$ を計算せよ．
  \item $z=1+\sqrt2\,i$ のとき，$z^4-2z^3+4z^2-2z+5$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $z^2=-5+12i$ を満たす複素数 $z$ を求めよ．
  \item $x$ の2次方程式 $(1+i)x^2+(a+3i)x+2(a+i)=0$ が実数解をもつような実数 $a$ の値と，そのときの2つの解を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\alpha=\dfrac{1+\sqrt3\,i}{2}$ について，$\alpha^{2026}$ を求めよ．
  \item $\dfrac{(1+i)^{10}}{(1-i)^{6}}$ を計算せよ．
\end{enumerate}

\begin{enumerate}
  \item $x^{2026}$ を $(x^2+1)(x-1)$ で割った余りを求めよ．
  \item $x^{2026}$ を $x^4+x^2+1$ で割った余りを求めよ．
\end{enumerate}

3次方程式 $x^3-2x^2+3x-4=0$ の3つの解を $\alpha,\beta,\gamma$ とする．
\begin{enumerate}
  \item $\alpha^2+\beta^2+\gamma^2$ の値を求め，3つの解がすべて実数ではないことを示せ．
  \item $\alpha^3+\beta^3+\gamma^3$ の値を求めよ．
  \item $(1-\alpha)(1-\beta)(1-\gamma)$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x^4+4$ を複素数の範囲で因数分解せよ．
  \item $x^2-x+1=0$ の2つの解を $\alpha,\beta$ とする．3次以下の整式 $f(x)$ が $f(\alpha)=\alpha+1$，$f(\beta)=\beta+1$，$f(0)=2$，$f(-1)=6$ を満たすとき，$f(x)$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x^2-2x+4=0$ の2つの解を $\alpha,\beta$ とする．$\alpha^3,\ \beta^3$ を解とする2次方程式（$x^2$ の係数は1）を求めよ．
  \item $x^3+2x^2-3x+1=0$ の3つの解を $\alpha,\beta,\gamma$ とする．$\alpha+\beta,\ \beta+\gamma,\ \gamma+\alpha$ を解とする3次方程式（$x^3$ の係数は1）を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x^2-(m-1)x+m=0$ の2つの解の比が $1:2$ となるような実数 $m$ を求めよ．
  \item $x^2-(k-3)x+k=0$ の2つの解（重解を含む）がともに整数となるような整数 $k$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item 実数 $a,b,c$ に対し，3つの2次方程式 $x^2+2ax+bc=0$，$x^2+2bx+ca=0$，$x^2+2cx+ab=0$ のうち少なくとも1つは実数解をもつことを示せ．
  \item $x^2-2(m-1)x+m+5=0$ が少なくとも1つの正の解をもつような実数 $m$ の範囲を求めよ．
\end{enumerate}

$\omega=\dfrac{-1+\sqrt3\,i}{2}$ とする．
\begin{enumerate}
  \item $(1+\omega)^{2026}+(1+\omega^2)^{2026}$ の値を求めよ．
  \item $\displaystyle\sum_{k=1}^{30}k\,\omega^k$ を $a+bi$（$a,b$ は実数）の形で表せ．
\end{enumerate}

2つの2次方程式 $x^2+kx+2=0$ …①，$x^2+2x+k=0$ …② について，
\begin{enumerate}
  \item ①，②がちょうど1つの共通解をもつような実数 $k$ と，その共通解を求めよ．
  \item ①，②が2つの共通解をもつような $k$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 実数係数の3次方程式 $x^3+ax^2+bx+10=0$ が $1-2i$ を解にもつとき，$a,b$ と他の解を求めよ．
  \item $\sqrt2+\sqrt3$ を解にもつ整数係数の4次方程式（$x^4$ の係数は1）を1つ求めよ．また，$\sqrt2+\sqrt3$ は有理数係数の2次方程式の解にはならないことを示せ．
\end{enumerate}

\begin{enumerate}
  \item $x$ の方程式 $(x-2)(x^2+ax+a+6)=0$ が重解をもつような実数 $a$ をすべて求めよ．
  \item $x^3-3x+k=0$ が重解をもつような実数 $k$ と，そのときの解を求めよ．
\end{enumerate}

次の方程式を複素数の範囲で解け．
\begin{enumerate}
  \item $(x+1)(x+2)(x+3)(x+4)=24$
  \item $x^4-4x^3+5x^2-4x+1=0$
\end{enumerate}

\begin{enumerate}
  \item $k\binom nk=n\binom{n-1}{k-1}$（$1\leqq k\leqq n$）を示せ．
  \item $\displaystyle\sum_{k=0}^nk^2\binom nk$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\sum_{k=0}^{10}\binom{10}{k}2^k$ を求めよ．
  \item $\displaystyle\sum_{k=0}^n\frac{1}{k+1}\binom nk$ を求めよ．
  \item $\displaystyle\sum_{k=0}^n\binom nk^2=\binom{2n}{n}$ を示せ．
\end{enumerate}

3次方程式 $x^3-x-1=0$ の3つの解を $\alpha,\beta,\gamma$ とし，$p_n=\alpha^n+\beta^n+\gamma^n$ とする．
\begin{enumerate}
  \item $p_1,\ p_2$ を求め，$p_{n+3}=p_{n+1}+p_n$ を示せ．
  \item $p_{10}$ を求めよ．
\end{enumerate}

$f(x)=x^3-3x+1$ とする．
\begin{enumerate}
  \item $f(x)=0$ は $-2<x<-1,\ 0<x<1,\ 1<x<2$ にそれぞれ1つずつ実数解をもつことを示せ．
  \item $\alpha$ が $f(x)=0$ の解ならば，$\alpha^2-2$ も $f(x)=0$ の解であることを示せ．
\end{enumerate}

3次方程式 $x^3-x+1=0$ の3つの解を $\alpha,\beta,\gamma$ とする．
\begin{enumerate}
  \item $\alpha^2+\beta^2+\gamma^2$，$\alpha^3+\beta^3+\gamma^3$ の値を求めよ．
  \item $\alpha^5+\beta^5+\gamma^5$ の値を求めよ．
  \item $\dfrac1{\alpha^2}+\dfrac1{\beta^2}+\dfrac1{\gamma^2}$ の値を求めよ．
\end{enumerate}

$\alpha=1+2i$ とする（$i$ は虚数単位）．
\begin{enumerate}
  \item $\alpha$ を解にもつ2次方程式 $x^2+px+q=0$（$p,q$ は実数）を求めよ．
  \item 整数 $a,b,c$ を係数とする3次方程式 $2x^3+ax^2+bx+c=0$ が $\alpha$ を解にもち，さらに $0<x<1$ の範囲に実数解をもつとき，$(a,b,c)$ を求めよ．
\end{enumerate}

$p,q,r$ を整数とし，$g(x)=x^3+px^2+qx+r$ とする．
\begin{enumerate}
  \item 有理数 $a$ が方程式 $g(x)=0$ の解ならば，$a$ は整数であることを示せ．
  \item $g(0)$ も $g(1)$ も奇数であるとき，方程式 $g(x)=0$ は有理数の解をもたないことを示せ．
\end{enumerate}

整式 $p(x)$ を $x-1$ で割った余りは $3$，$(x+1)^2$ で割った余りは $2x-1$ である．
\begin{enumerate}
  \item $p(x)$ を $(x-1)(x+1)^2$ で割った余りを求めよ．
  \item $xp(x)$ を $(x-1)(x+1)^2$ で割った余りを求めよ．
  \item $\{p(x)\}^2$ を $(x+1)^2$ で割った余りを求めよ．
\end{enumerate}

\begin{enumerate}
  \item 正の実数 $x,y$ に対して $(x+y)\Bigl(\dfrac1x+\dfrac4y\Bigr)\geqq9$ を示し，等号が成立する条件を求めよ．
  \item 正の実数 $a,b,c$ が $a+b+c=1$ を満たすとき，$\dfrac1a+\dfrac4b+\dfrac9c$ の最小値と，そのときの $a,b,c$ を求めよ．
\end{enumerate}

$a,b$ を実数とする．
\begin{enumerate}
  \item 実数 $x\neq0$ に対して $t=x+\dfrac1x$ のとりうる値の範囲を求めよ．また，$t$ の値1つに対応する実数 $x$ の個数を調べよ．
  \item 方程式 $x^4+ax^3+bx^2+ax+1=0$ が異なる4個の実数解をもつような点 $(a,b)$ の範囲を求めよ．
\end{enumerate}

次の2条件（イ），（ロ）を同時にみたす整数 $a,b$ の組 $(a,b)$ をすべて求めよ．
\begin{enumerate}
  \item[（イ）] 2次方程式 $X^2+aX+b=0$ の2つの解（重解を含む）がともに2以上の整数である．
  \item[（ロ）] 不等式 $5a+3b\leqq0$ が成り立つ．
\end{enumerate}

$n=1,2,\dots$ に対して $Q_n(x)=x^3-nx^2+(n-3)x+1$ とする．
\begin{enumerate}
  \item $Q_n(x)=0$ は $x<0$，$0<x<1$，$x>1$ にそれぞれ1つずつ実数解をもつことを示せ．
  \item $t$ が $Q_n(x)=0$ の解であるとき，$Q_n\Bigl(\dfrac1{1-t}\Bigr)=0$ であることを示せ．
  \item 最大の実数解を $\alpha_n$ とする．他の2解を $\alpha_n$ で表し，最小の実数解 $\beta_n$ について $\displaystyle\lim_{n\to\infty}n\beta_n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $0<a<b$，$c_0>c_1>0$ のとき $ac_1+bc_0>ac_0+bc_1$ を示せ．
  \item $n$ 個の自然数 $x_1,\dots,x_n$ は互いに相異なり，$1\leqq x_k\leqq n\ (1\leqq k\leqq n)$ をみたす．このとき
  \[ \sum_{k=1}^n\frac{x_k^2}{k(k+1)}\geqq n+1-\sum_{k=1}^{n+1}\frac1k \]
  を示せ．
\end{enumerate}

$a=\tan^2\dfrac\pi5$，$b=\tan^2\dfrac{2\pi}5$ とおく．
\begin{enumerate}
  \item $a+b$ および $ab$ は整数であることを示せ．
  \item 任意の自然数 $n$ に対し，$a^n+b^n$ は $5^{\lceil n/2\rceil}$ の倍数である整数であることを示せ（$\lceil x\rceil$ は $x$ 以上の最小の整数）．
\end{enumerate}

$x$ に関する方程式 $a^2x^3+x-2a=0\cdots(*)$ について，
\begin{enumerate}
  \item $(*)$ が $x=\frac12$ を解にもつような $a$ の値を求めよ．
  \item $a$ が正の数全体を動くとき，$(*)$ の実数解がとる値の範囲を求めよ．
\end{enumerate}

$n\geqq2$ を整数，$a,b$ を実数とし，$f(x)=x^n-ax-b$ とする．
\begin{enumerate}
  \item $f(x)$ が $x^2-x-2$ で割り切れるとき，$a,b$ を $n$ で表せ．
  \item $f(x)$ が $(x-1)^2$ で割り切れるとき，$a,b$ を $n$ で表せ．
\end{enumerate}

$\omega=\dfrac{-1+\sqrt3i}2$ とする．
\begin{enumerate}
  \item $\omega+1$ を $\omega$ の累乗で表し，$(\omega+1)^6$ の値を求めよ．
  \item $n$ を自然数とする．$(x+1)^n$ を $x^2+x+1$ で割った余りを，$n$ を6で割った余りで場合分けして求めよ．
\end{enumerate}

3次方程式 $x^3+6x-20=0\ \cdots$① を考える．
\begin{enumerate}
  \item $u^3+v^3=20$，$uv=-2$ をみたす $u,v$ に対し $x=u+v$ は①の解であることを示せ．
  \item $u^3,v^3$ を求め，実数 $u,v$ を求めよ．
  \item ①の実数解と虚数解をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x^3+ax^2+bx-10=0$（$a,b$ 実数）が $x=1+2i$ を解にもつとき，$a,b$ と実数解を求めよ．
  \item $x^4-4x^3+ax^2+bx+10=0$（$a,b$ 実数）が $2+i$ を解にもつとき，$a,b$ と他の解をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$，$y>0$ のとき $\Bigl(x+\dfrac2y\Bigr)\Bigl(y+\dfrac8x\Bigr)$ の最小値を求めよ．
  \item $x>-3$ のとき $\dfrac{x+3}{x^2+2x+6}$ の最大値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x^3+y^3+z^3-3xyz=(x+y+z)(x^2+y^2+z^2-xy-yz-zx)$ を用いて，正の数 $x,y,z$ に対し $x^3+y^3+z^3\geqq3xyz$ を示せ．
  \item 正の数 $a,b,c$ が $abc=3(a+b+c)+28$ をみたしながら変化するとき，$abc$ の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 実数 $a,b,x,y$ に対して $(ax+by)^2\leqq(a^2+b^2)(x^2+y^2)$ を示せ．
  \item (1) を2回使って，実数 $a,b,c,x,y,z$ に対し $(ax+by+cz)^2\leqq(a^2+b^2+c^2)(x^2+y^2+z^2)$ を示せ．
  \item $x+2y+3z=7$ のとき，$x^2+y^2+z^2$ の最小値とそのときの $x,y,z$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $a\geqq b\geqq c$，$x\geqq y\geqq z$ のとき $3(ax+by+cz)\geqq(a+b+c)(x+y+z)$ を示せ．
  \item 正の数 $a,b,c$ に対して $\dfrac{a^2}{b+c}+\dfrac{b^2}{c+a}+\dfrac{c^2}{a+b}\geqq\dfrac{a+b+c}2$ を示せ．
\end{enumerate}

\begin{enumerate}
  \item $(x^2+2)^8+(2x^2-1)^7$ の展開式における $x^4$ の係数を求めよ．
  \item $(x^2+x-2)^8$ の展開式における $x^5$ の係数を求めよ．
\end{enumerate}

実数 $a$ に対して $f(x)=x^4+ax^3+(a^2-6)x^2+ax+1$ とする．
\begin{enumerate}
  \item $x\neq0$ に対して $t=x+\dfrac1x$ とするとき，$\dfrac{f(x)}{x^2}$ を $a$ と $t$ で表せ．
  \item $x$ が0でない実数全体を動くとき，$t$ のとりうる値の範囲を求めよ．
  \item 方程式 $f(x)=0$ が少なくとも1つ実数解をもつような $a$ の範囲を求めよ．
\end{enumerate}

$a_1,a_2,\dots$ を正の実数とする．
\begin{enumerate}
  \item $\dfrac{a_1+a_2+a_3+a_4}4\geqq\sqrt[4]{a_1a_2a_3a_4}$ を，2個の場合の不等式を用いて証明せよ．
  \item (1) で $a_4=\dfrac{a_1+a_2+a_3}3$ とおくことにより，$\dfrac{a_1+a_2+a_3}3\geqq\sqrt[3]{a_1a_2a_3}$ を証明せよ．
  \item $x>0$ のとき，$x^2+\dfrac{16}x$ の最小値とそのときの $x$ を求めよ．
\end{enumerate}

2次方程式 $x^2-6x+4=0$ の2つの解を $\alpha,\beta$（$\alpha>\beta$）とし，$s_n=\alpha^n+\beta^n$ とする．
\begin{enumerate}
  \item $s_2,s_3$ を求めよ．
  \item すべての自然数 $n$ に対して，$s_n$ は $2^n$ で割り切れることを示せ．
  \item すべての自然数 $n$ に対して，$[\alpha^n]$ は奇数であることを示せ．さらに $n\geqq2$ のとき $[\alpha^n]$ を4で割った余りを求めよ．
\end{enumerate}

実数 $a,b$ に対し，$x$ の4次方程式 $x^4+ax^3+bx^2+ax+1=0$ ……(★) を考える．
\begin{enumerate}
  \item $z=x+\dfrac1x$ とおくとき，(★) を $z$ の方程式で表せ．
  \item 実数 $z$ に対し，$x+\dfrac1x=z$ をみたす $x$ がすべて実数であるための条件は $|z|\geqq2$ であることを示せ．
  \item (★) の4つの解（重解は重複して数える）がすべて実数となるような点 $(a,b)$ の範囲を求め，$ab$ 平面上に図示せよ．
\end{enumerate}

\begin{enumerate}
  \item $2\cos3\theta=(2\cos\theta)^3-3(2\cos\theta)$ を示せ．
  \item $2\cos\dfrac{2\pi}9$，$2\cos\dfrac{4\pi}9$，$2\cos\dfrac{8\pi}9$ はすべて3次方程式 $x^3-3x+1=0$ の解であることを示せ．
  \item $\cos\dfrac{2\pi}9\cos\dfrac{4\pi}9\cos\dfrac{8\pi}9$ の値を求めよ．
  \item $\cos^2\dfrac{2\pi}9+\cos^2\dfrac{4\pi}9+\cos^2\dfrac{8\pi}9$ の値を求めよ．
\end{enumerate}

方程式 $x^2+x+1=0$ の解の1つを $\omega$ とする．$m$ は正の整数とする．
\begin{enumerate}
  \item $n$ を整数とするとき，$1+\omega^n+\omega^{2n}$ の値を求めよ．
  \item $(1+\omega)^{3m}$，$(1+\omega^2)^{3m}$ の値を求めよ．
  \item $\displaystyle\sum_{k=0}^{m-1}{}_{3m}\mathrm C_{3k+1}=\frac{2^{3m}-(-1)^m}3$ を示せ．
\end{enumerate}

$f(x)$ を整数を係数とする整式とし，$g(x)=x^2+1$ とする．すべての正の整数 $n$ に対して $\dfrac{f(n)}{g(n)}$ は整数であるとする．
\begin{enumerate}
  \item $f(x)=g(x)q(x)+rx+s$ と割ったとき，$q(x)$ は整数係数の整式，$r,s$ は整数であることを示せ．
  \item $f(x)$ は $g(x)$ で割り切れることを示せ．
\end{enumerate}

4次方程式 $x^4+4x-1=0$ ……① を考える．
\begin{enumerate}
  \item ①を $(x^2+t)^2=2tx^2-4x+t^2+1$ と変形する．右辺が $x$ の1次式の完全平方となるための $t$ の条件を求め，それをみたす実数 $t$ を1つ求めよ．
  \item ①の実数解をすべて求めよ．
  \item ①の虚数解をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $a,b,c$ は整数で $0<a<b<c$ とする．整式 $f(x)=x(x-a)(x-b)-30$ が $x-c$ で割り切れるような $(a,b,c)$ をすべて求めよ．
  \item $(x+1)^{10}$ を $(x-1)^2(x+1)$ で割った余りを求めよ．
  \item 正の整数 $n$ と実数 $k$ について，$x^n+y^n+z^n-kxyz$ が $x+y+z$ で割り切れるような $(n,k)$ をすべて求めよ．
\end{enumerate}

整式 $f(x)$ と定数 $a,b,c$ について，$f(x)$ を $(x+1)(x+2)$ で割ると余り $5x+7$，$(x+2)(x+3)$ で割ると余り $2x+a$，$(x+1)(x+3)$ で割ると余り $bx+c$ である．
\begin{enumerate}
  \item $a$ の値を求めよ．
  \item このような $f(x)$ のうち次数が最小のものを求めよ．
  \item $b,c$ の値を求めよ．
\end{enumerate}

$f_n(x)=x^{2n}-x^n+1$（$n$ は自然数）とする．
\begin{enumerate}
  \item $f_n(x)$ が $x^2-x+1$ で割り切れるような $n$ をすべて求めよ．
  \item どんな $n$ に対しても，$f_n(x)$ は $(x^2-x+1)^2$ で割り切れないことを示せ．
\end{enumerate}

\begin{enumerate}
  \item 2次方程式 $x^2+mx-24=0$ の2解がともに有理数となるような自然数 $m$ をすべて求めよ．
  \item 実数 $a$ に対し，3次方程式 $x^3-ax^2+(3a+3)x+(a-2)(a-15)=0$ の解がすべて自然数であるとき，$a$ の値と3解を求めよ．
\end{enumerate}

$f(x)=\dfrac{ax-2}{x+1}$ とし，$f_1=f$，$f_{n+1}(x)=f(f_n(x))$ とする．
\begin{enumerate}
  \item $f_2(x)$ を求めよ．
  \item $f_2(x)=x$ が恒等的に成り立つような $a$ の値を求めよ．
  \item $f_2(x)=x$ は恒等的には成り立たないが，$f_4(x)=x$ が恒等的に成り立つような $a$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $f(x)=2x+|x-1|$ のグラフを描き，$f$ が増加関数であることを示せ．
  \item $g(x)=ax+b-|cx+d|$（$c\geqq0$）が $f$ の逆関数となるように $a,b,c,d$ を定めよ．
\end{enumerate}

次の条件 (a)，(b) をともにみたす実数の組 $(p,q,r)$ をすべて求めよ．
\begin{enumerate}
  \item[(a)] $|p|=|q|=2|r|$
  \item[(b)] 3次方程式 $x^3+px^2+qx+r=0$ は，絶対値が1であるような虚数解をもつ．
\end{enumerate}

\begin{enumerate}
  \item $(x^2+2)^5$ の展開式における $x^6$ の係数を求めよ．
  \item $(x^2+x-1)^4$ の展開式における $x^3$ の係数と $x^5$ の係数を求めよ．
  \item $(x^2+2)^5(x^2+x-1)^4$ の展開式における $x^{11}$ の係数を求めよ．
\end{enumerate}

$n$ は3以上の整数とする．
\begin{enumerate}
  \item $x>0$ のとき，$(1+x)^n>1+nx+\dfrac{n(n-1)}2x^2$ を示せ．
  \item $\sqrt[n]n=1+h_n$（$h_n>0$）とおくとき，$h_n<\sqrt{\dfrac2{n-1}}$ を示せ．
  \item $\sqrt[100]{100}<1.15$ を示せ．
\end{enumerate}

実数 $\alpha,\beta,\gamma$ が $\alpha+\beta+\gamma=2$ をみたしている．$p=\alpha\beta+\beta\gamma+\gamma\alpha$，$q=\alpha\beta\gamma$ とおく．
\begin{enumerate}
  \item $p=q+1$ のとき，$\alpha,\beta,\gamma$ の少なくとも1つは1であることを示せ．
  \item $p=\dfrac43$ のとき，$\alpha,\beta,\gamma$ はすべて等しいことを示し，その値を求めよ．
\end{enumerate}

実数 $a,b,c$ が $(a+b+c)^3=a^3+b^3+c^3$ をみたしている．
\begin{enumerate}
  \item $a+b$，$b+c$，$c+a$ のいずれかは0であることを示せ．
  \item $n$ が正の奇数のとき，$(a+b+c)^n=a^n+b^n+c^n$ を示せ．
  \item $abc\neq0$ のとき，$\dfrac1{a^5}+\dfrac1{b^5}+\dfrac1{c^5}=\left(\dfrac1a+\dfrac1b+\dfrac1c\right)^5$ を示せ．
\end{enumerate}

0でない実数 $a,b,c$ が $\dfrac{2a+b}c=\dfrac{2b+c}a=\dfrac{2c+a}b$ をみたしている．
\begin{enumerate}
  \item この共通の値を $k$ とするとき，$k=3$ であることを示せ．
  \item $\dfrac{(a+b)(b+c)(c+a)}{abc}$ の値を求めよ．
\end{enumerate}

$a,b,c,d,x$ は実数とする．
\begin{enumerate}
  \item $(a^2+2b^2+3)x^2-2(ac+2bd+3)x+c^2+2d^2+3\geqq0$ を示せ．
  \item $(a^2+2b^2+3)(c^2+2d^2+3)\geqq(ac+2bd+3)^2$ を示し，等号が成り立つ条件を求めよ．
  \item $a^2+2b^2=3$，$ac+2bd=9$ のとき，$c^2+2d^2$ の最小値を求めよ．
\end{enumerate}

$a,b,c,d$ はすべて $0$ より大きく $1$ より小さい数とする．
\begin{enumerate}
  \item 4つの不等式 $a(1-b)>\frac14$，$b(1-c)>\frac14$，$c(1-d)>\frac14$，$d(1-a)>\frac14$ は同時には成り立たないことを示せ．
  \item $a(1-b)$，$b(1-c)$，$c(1-d)$，$d(1-a)$ がすべて等しい値 $t$ をとるとき，$t\leqq\frac14$ であることと，$t=\frac14$ となる $a,b,c,d$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $z^2=-5+12i$ となる複素数 $z$ を求めよ．
  \item $w^3=52+47i$ となる複素数 $w$ のうち，実部・虚部がともに整数であるものを求めよ．
\end{enumerate}

$k$ を0と異なる実数とする．方程式 $x^2+(1+3i)x+k(1+i)^2=0$ をみたす実数 $x$ が存在するとし，それを $\alpha$ とする．
\begin{enumerate}
  \item $k$ と $\alpha$ の値を求めよ．
  \item この方程式をみたす複素数をすべて求めよ．
\end{enumerate}

$a$ を実数とする2次方程式 $x^2+ax+2a-5=0$ について答えよ．
\begin{enumerate}
  \item 任意の $a$ に対して異なる2つの実数解をもつことを示せ．
  \item 2つの解が異符号となる $a$ の範囲を求めよ．
  \item 2つの解 $\alpha,\beta$ について $3<|\alpha-\beta|<5$ となる $a$ の範囲を求めよ．
\end{enumerate}

$f(x)=ax^2+bx+c$ と整式 $g(x)$ が $x^2f(x)=(x-2)g(x)$ をみたし，$g(2)=4$ である．
\begin{enumerate}
  \item $4a+2b+c$ の値を求めよ．
  \item $b$ を $a$ で表せ．
  \item $g(x)-4$ が $(x-2)^2$ で割り切れるとき，$a,b,c$ の値と $g(x)$ を求めよ．
\end{enumerate}

整式 $P(x)$ を $x-2$ で割ると $3$ 余り，$x+1$ で割ると $-3$ 余る．
\begin{enumerate}
  \item $P(x)$ を $(x-2)(x+1)$ で割った余りを求めよ．
  \item $P(x)$ を $(x+1)^2$ で割った余りが定数であるとき，$P(x)$ を $(x+1)^2(x-2)$ で割った余りを求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x^{20}$ を $x^3-1$ で割った余りを求めよ．
  \item $x^{20}+3x^{16}-x^7$ を $x^3-1$ で割った余り，$x^2+x+1$ で割った余りを求めよ．
  \item $x^{20}+ax^{10}+bx^8+3x+4$ が $x^2+x+1$ で割り切れるとき，実数 $a,b$ を求めよ．
  \item $x^{102}-1$ を $x^3+x^2+x+1$ で割った余りを求めよ．
\end{enumerate}

\begin{enumerate}
  \item $a=\dfrac1{4-\sqrt{13}}$ の整数部分 $b$ と小数部分 $c$ を求めよ．
  \item (1) の $a,c$ について，方程式 $x^3-3x^2+1=0$ は $c<x<a$ の範囲に解をもつことを示せ．
\end{enumerate}

4次方程式 $x^4-3x^3-4x^2+9x+9=0$ ……① は $y=x+\dfrac ax$ のおき換えにより $y^2+by+c=0$ になる．
\begin{enumerate}
  \item $a,b,c$ を求めよ．
  \item ① を解け．
\end{enumerate}

3次方程式 $x^3+px^2+qx+r=0$ が3重解 $\beta$ をもつ（左辺 $=(x-\beta)^3$）とする．
\begin{enumerate}
  \item $p,q,r$ を $\beta$ で表せ．
  \item $p,q$ が整数のとき，$\beta$ は整数であり，$r$ も整数であることを示せ．
  \item 4次方程式 $x^4+px^3+qx^2+rx+s=0$ が4重解 $\beta$ をもち，$p,q$ が整数のとき，$\beta,r,s$ はすべて整数であることを示せ．
\end{enumerate}

$f(x)=x^2-2x+c$（$c$ は実数）とおく．
\begin{enumerate}
  \item $f(f(x))-x$ を $f(x)-x$ で割った商を求めよ．
  \item 方程式 $f(f(x))=x$ が異なる4つの実数解をもつための $c$ の条件を求めよ．
\end{enumerate}

$k$ を実数とする．$f(x)=x^3-kx^2+2$ に対し，$f(x)=0$ の3つの解を $\alpha,\beta,\gamma$ とする．$g(x)$ は $x^3$ の係数が1の3次式で，$g(x)=0$ の3つの解が $\alpha\beta$，$\beta\gamma$，$\gamma\alpha$ である．
\begin{enumerate}
  \item $g(x)$ を $k$ を用いて表せ．
  \item $f(x)=0$ と $g(x)=0$ が共通の実数解をもつような実数 $k$ の値を求め，そのときの共通解を求めよ．
\end{enumerate}

実数 $a,b$ に対し，4次方程式 $x^4+ax^3+bx^2+ax+1=0$ ……① を考える．
\begin{enumerate}
  \item $z=x+\frac1x$ とおいて①を $z$ の方程式で表せ．
  \item ①の4つの解がすべて絶対値1であるための必要十分条件は，(1) の方程式の解がともに $-2$ 以上2以下の実数であることを示せ．
  \item (2) の条件をみたす点 $(a,b)$ の範囲を図示し，その面積を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x^5+ax^2+b$ が $(x-1)^2$ で割り切れるような $a,b$ を求めよ．
  \item 自然数 $n\geqq2$ に対し，$x^n$ を $(x-1)^2$ で割った余りを求めよ．
  \item 曲線 $y=x^n$ の点 $(1,1)$ における接線の方程式を，(2) を用いて答えよ．
\end{enumerate}

実数 $x,y,z$ が $x+y+z=6$，$xy+yz+zx=9$ をみたす．
\begin{enumerate}
  \item $xyz$ のとり得る値の範囲を求めよ．
  \item $x\leqq y\leqq z$ とするとき，$z$ のとり得る値の範囲を求めよ．
  \item さらに $x,y,z\geqq\frac12$ という条件を加えたとき，$xyz$ のとり得る値の範囲を求めよ．
\end{enumerate}

実数 $x,y$ が $x^3+y^3=3xy$ をみたすとき，
\begin{enumerate}
  \item $x+y$ のとり得る値の範囲を求めよ．
  \item $xy$ のとり得る値の範囲を求めよ．
\end{enumerate}

$k$ を実数として，3次方程式 $x^3+(k-2)x^2-kx-2k=0$ ……① を考える．
\begin{enumerate}
  \item ①は $k$ によらず $x=2$ を解にもつことを示し，左辺を因数分解せよ．
  \item ①が異なる3個の実数解をもつような $k$ の範囲を求めよ．
  \item ①の異なる実数解がちょうど2個となる $k$ をすべて求め，それぞれの解を答えよ．
\end{enumerate}

4次方程式 $x^4-3x^3+2x^2+5x-1=0$ の4つの解を $\alpha,\beta,\gamma,\delta$ とする．次の値を求めよ．
\begin{enumerate}
  \item $(2-\alpha)(2-\beta)(2-\gamma)(2-\delta)$
  \item $(\alpha^2+1)(\beta^2+1)(\gamma^2+1)(\delta^2+1)$
  \item $(\alpha^2-\alpha+1)(\beta^2-\beta+1)(\gamma^2-\gamma+1)(\delta^2-\delta+1)$
\end{enumerate}

$a=x^2-yz$，$b=y^2-zx$，$c=z^2-xy$ とおく．
\begin{enumerate}
  \item $a-b=(x-y)(x+y+z)$ を示せ．
  \item $a^2-bc=x(x^3+y^3+z^3-3xyz)$ を示せ．同様に $b^2-ca$，$c^2-ab$ も表せ．
  \item 連立方程式 $x^2-yz=7$，$y^2-zx=-5$，$z^2-xy=1$ を，$x+y+z>0$ のもとで解け．
\end{enumerate}

$n$ を自然数とし，$(x^2+1)^n$ を $x^4+x^2+1$ で割った余りを $R_n(x)$ とする．
\begin{enumerate}
  \item $R_n(x)$ は $px^2+q$（$p,q$ は実数）の形であることを示せ．
  \item $R_{50}(x)$ を求めよ．
  \item $R_n(x)$ が定数となるような $n$ をすべて求め，そのときの $R_n(x)$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 任意の整式 $f(x)$ について，$f(f(x))-x$ は $f(x)-x$ で割り切れることを示せ．
  \item $f(x)=x^2+c$（$c$ は実数）のとき，$f(f(x))-x$ を $f(x)-x$ で割った商を求めよ．
  \item 方程式 $f(f(x))=x$ が相異なる4個の実数解をもつような $c$ の値の範囲を求めよ．
\end{enumerate}

$n$ を3以上の整数とする．
\begin{enumerate}
  \item $x^n$ を $(x-1)^3$ で割った余りを求めよ．
  \item $x^{2n}$ を $(x^2+1)^2$ で割った余りを求めよ．
\end{enumerate}

実数 $a,b$ に対して $f(x)=x^2+ax+b$ とする．
\begin{enumerate}
  \item $f(x^2)$ が $f(x)$ で割り切れるような $f(x)$ をすべて求めよ．
  \item (1) のうち，任意の自然数 $n$ について $f(x^n)$ が $f(x)$ で割り切れるものをすべて求めよ．
\end{enumerate}

実数係数の3次方程式 $x^3+ax^2+bx+c=0$ が相異なる3つの実数解をもち，それらは適当に並べると等差数列に，別の並べ方をすると等比数列になる．さらに3解の2乗の和が84である．
\begin{enumerate}
  \item 3解は，0でない実数 $t$ を用いて $t,\,-2t,\,4t$ と表されることを示せ．
  \item $(a,b,c)$ をすべて求め，それぞれの場合の3解を小さい順に並べよ．
\end{enumerate}

solutions.tex:
$g(x)=0$ の解は $r=-1\pm s$（$s=\sqrt{1-a}>0$，$a<1$）．$g(x)=r\iff(x+1)^2=r+1-a=s^2\pm s-1$．
$s^2+s-1>s^2-s-1$ で，$s^2+s-1>0\iff s>\frac{\sqrt5-1}2$，$s^2-s-1>0\iff s>\frac{1+\sqrt5}2$．$a=1-s^2$ に直すと
\begin{itemize}
  \item $\boldsymbol{a<\dfrac{-1-\sqrt5}2}$：\textbf{4個}
  \item $\boldsymbol{a=\dfrac{-1-\sqrt5}2}$：\textbf{3個}
  \item $\boldsymbol{\dfrac{-1-\sqrt5}2<a<\dfrac{\sqrt5-1}2}$：\textbf{2個}
  \item $\boldsymbol{a=\dfrac{\sqrt5-1}2}$：\textbf{1個}（$x=-1$）
  \item $\boldsymbol{\dfrac{\sqrt5-1}2<a<1}$：\textbf{0個}
\end{itemize}
3個のとき $s=\frac{1+\sqrt5}2$，$(x+1)^2=0$ または $(x+1)^2=2s=1+\sqrt5$．
\textbf{解は $x=-1,\ -1\pm\sqrt{1+\sqrt5}$}．

statement.tex:
$f(x)=x^3+ax^2+bx+c$（$a,b,c$ は実数）とし，$|a|,|b|,|c|$ の最大値を $m$（$m>0$）とする．
\begin{enumerate}
  \item 方程式 $f(x)=0$ の任意の解 $z$（虚数解も含む）について $|z|<1+m$ であることを示せ．
  \item $f(x)=x^3-mx^2-mx-m$ の最大の実数解を $R_m$ とする．$m<R_m<1+m$ を示し，$\displaystyle\lim_{m\to\infty}(1+m-R_m)=0$ を示せ．
\end{enumerate}

\begin{enumerate}
  \item 実数係数の1次以下の整式 $A(x),B(x),C(x),D(x)$ が $\{A(x)\}^2+\{B(x)\}^2+\{C(x)\}^2=\{D(x)\}^2$ をみたし，$D(x)$ は定数でないとする．このとき $A(x),B(x),C(x)$ はいずれも $D(x)$ の定数倍であることを示せ．
  \item 2次の整式では (1) と同様の主張が成り立たないことを，$\{A(x)\}^2+\{B(x)\}^2=\{D(x)\}^2$ をみたし $A(x)$ が $D(x)$ の定数倍でない例をあげて示せ．
\end{enumerate}

$x$ についての方程式 $x^3+ax^2+bx+c=0$ が相異なる3つの解 $\alpha,\beta,\gamma$ をもち，$\alpha^2,\beta^2,\gamma^2$ もこの同じ方程式の3つの解であるとする．
\begin{enumerate}
  \item $\alpha^2,\beta^2,\gamma^2$ は相異なり，写像 $z\mapsto z^2$ は $\{\alpha,\beta,\gamma\}$ をそれ自身に1対1にうつすことを示せ．
  \item $a,b,c$ が実数のとき，$(a,b,c)$ と3つの解をすべて求めよ．
  \item $a,b,c$ を複素数としてよいとき，(2) 以外に条件をみたす方程式をすべて求めよ．
\end{enumerate}

整式 $f(x)$ を $(x-1)^2$ で割ったときの余りは $3x-1$，$(x+1)^3$ で割ったときの余りは $2x^2+x+1$ である．
\begin{enumerate}
  \item $f(x)$ を $(x-1)^2(x+1)$ で割った余りを求めよ．
  \item $f(x)$ を $(x-1)^2(x+1)^3$ で割った余りを求めよ．
  \item $f(x)$ が最高次の係数1の5次式であるとき，$f(x)$ を求めよ．
\end{enumerate}

正の整数 $n$ に対し，$f(z)=z^{2n}+z^n+1$ とする．
\begin{enumerate}
  \item $z^6-1$ は $z^4+z^2+1$ で割り切れることを示せ．
  \item $f(z)$ を $z^4+z^2+1$ で割ったときの余りを，$n$ を6で割った余りによって分類して求めよ．
  \item $f(z)$ が $z^4+z^2+1$ で割り切れるような $n$ をすべて求めよ．
\end{enumerate}

実数を係数とする3次方程式 $x^3+px^2+qx+r=0$ は，相異なる虚数解 $\alpha,\beta$ と実数解 $\gamma$ をもつとする．
\begin{enumerate}
  \item $\beta=\bar\alpha$ を証明せよ．
  \item $\alpha$ の虚部が1であり，$\alpha\beta+\beta\gamma+\gamma\alpha=1$ をみたし，さらに複素数平面上で $\alpha,\beta,\gamma$ を表す3点が $\gamma$ を直角の頂点とする直角二等辺三角形をなすとする．実数の組 $(p,q,r)$ をすべて求めよ．
\end{enumerate}

$f(x)$ を整式とする．
\begin{enumerate}
  \item 関数 $y=f(x)$ のグラフがある点 $(p,q)$ に関して対称であることは，ある整式 $g(u)$ を用いて $f(x)=q+(x-p)\,g\bigl((x-p)^2\bigr)$ と書けることと同値であることを示せ．
  \item $f(x)=x^5-5x^4+7x^3-x^2-2x+4$ のグラフは点対称であることを示し，対称の中心と (1) の $g(u)$ を求めよ．
  \item $y=x^4+x$ のグラフは，どの点に関しても点対称でなく，$y$ 軸に平行などの直線に関しても線対称でないことを示せ．
\end{enumerate}

$f(x)=x^4-8x^3+18x^2+cx+d$ とする．
\begin{enumerate}
  \item $y=f(x)$ のグラフが $y$ 軸に平行なある直線に関して対称となる $c$ の値を求めよ．
  \item (1) のとき，$f(x)$ を2つの2次関数の合成 $g(h(x))$（$h(x)$ の $x^2$ の係数は1）で表せ．
  \item (1) のとき，方程式 $f(x)=0$ が相異なるちょうど3個の実数解をもつような $d$ の値を求めよ．
\end{enumerate}

$n,k$ を正の整数とし，$P(x)$ を実数係数の $n$ 次以上の整式とする．
\begin{enumerate}
  \item $Q(x)$ を整数係数の整式で $Q(0)=\pm1$ をみたすものとする．$Q(x)^kP(x)$ の $n$ 次以下の項の係数がすべて整数ならば，$P(x)$ の $n$ 次以下の項の係数もすべて整数であることを示せ．
  \item $Q(x)=2+x$，$k=3$，$n=3$ のとき (1) の結論が成り立たない例として，$(2+x)^3P(x)$ の3次以下の係数がすべて整数で，$P(0)$ が整数でない3次式 $P(x)$ を1つ求めよ．
  \item $(1+x)^kP(x)$ の $n$ 次以下の項の係数がすべて偶数ならば，$P(x)$ の $n$ 次以下の項の係数もすべて偶数であることを示せ．
\end{enumerate}

自然数 $n$ に対して，$x^n$ を $x^2+ax+b$ で割った余りを $r_nx+s_n$ とする．次の2条件 (イ)，(ロ) を考える．
\begin{itemize}
  \item[(イ)] $x^2+ax+b=(x-\alpha)(x-\beta)$，$\alpha\geqq\beta>0$ と表せる．
  \item[(ロ)] すべての自然数 $n$ に対して $r_n<r_{n+1}$ が成り立つ．
\end{itemize}
\begin{enumerate}
  \item $\alpha>\beta$ のとき，(ロ) はすべての自然数 $n$ に対して $\alpha^n(\alpha-1)>\beta^n(\beta-1)$ が成り立つことと同値であることを示せ．
  \item (イ)，(ロ) がともに成り立つための $\alpha$ の条件を求めよ．
  \item (イ)，(ロ) がともに成り立つような点 $(a,b)$ の存在範囲を不等式で表せ．
\end{enumerate}

整数 $a,b,c,d$ は $ad-bc=1$ をみたすとする．座標平面上の点 $(x,y)$ を点 $(ax+by,\ cx+dy)$ に移す移動を $f$ とし，$f$ を $k$ 回続けて行う移動を $f^k$ と書く．
\begin{enumerate}
  \item 「$f^4$ がすべての点をそれ自身に移し，かつ $f^2$ がそれ自身と異なる点に移す点が存在する」ことは，$a+d=0$ であることと同値であることを示せ．
  \item (1) の条件をみたす整数の組 $(a,b,c,d)$ が無限個存在することを示せ．
  \item (1) の条件をみたす $(a,b,c,d)$ のうち，$a,b,c,d$ がすべて $-3$ 以上3以下であるものの個数を求めよ．
\end{enumerate}

$\alpha$ を3次方程式 $x^3-3x+1=0$ の解の1つとする．以下で「$\alpha$ の2次式」とは，有理数 $p,q,r$ を用いた $p\alpha^2+q\alpha+r$ の形の式を指す．
\begin{enumerate}
  \item 有理数 $p,q,r$ が $p\alpha^2+q\alpha+r=0$ をみたせば $p=q=r=0$ であることを示せ．
  \item $(\alpha^2+\alpha-1)^2$ と $\dfrac1{\alpha+2}$ をそれぞれ $\alpha$ の2次式で表せ．
  \item $\alpha^2-2$ も $x^3-3x+1=0$ の解であることを示し，$\alpha$ 以外の2つの解をともに $\alpha$ の2次式で表せ．
\end{enumerate}

\begin{enumerate}
  \item $t>0$ に対して
\[f(t)=\sqrt t+\frac1{\sqrt t}+\sqrt{t+\frac1t-1},\qquad g(t)=\sqrt t+\frac1{\sqrt t}-\sqrt{t+\frac1t-1}\]
とおく．$f(t)$ の最小値と $g(t)$ の最大値を求めよ．
  \item $a=\sqrt{x^2-xy+y^2}$，$b=p\sqrt{xy}$，$c=x+y$ とおく．任意の正の数 $x,\ y$ に対して，$a,\ b,\ c$ を3辺の長さとする三角形がつねに存在するような実数 $p$ の値の範囲を求めよ．
\end{enumerate}

$x>0,\ y>0,\ x+y=s$（$s$ は正の定数）とし，$E=\left(x+\dfrac1x\right)\left(y+\dfrac1y\right)$ とおく．
\begin{enumerate}
  \item $s=1$ のとき，$E$ の最小値を求めよ．また，「$x+\frac1x\geqq2$，$y+\frac1y\geqq2$ より $E$ の最小値は4」という推論の誤りを指摘せよ．
  \item 一般の $s>0$ に対し，$E$ の最小値を $s$ で表せ．
\end{enumerate}

$a,\ b,\ c$ を実数とし，$f(x)=x^4-4x^3+ax^2+bx+c$ とする．
\begin{enumerate}
  \item 曲線 $y=f(x)$ が $y$ 軸に平行なある直線に関して対称となるための $a,\ b$ の条件を求めよ．また，そのときの対称軸を求めよ．
  \item (1)の条件のもとで，方程式 $f(x)=0$ が異なる4つの実数解をもち，それらを小さい順に並べると等差数列をなすための $a,\ c$ の条件を求めよ．
  \item (2)の条件をみたし，さらに $f(x)$ の最小値が $-16$ となるような $a,\ b,\ c$ を求めよ．
\end{enumerate}

実数 $a,\ b,\ c$ に対して $p(x)=x^3+ax^2+bx+c$ とする．
\begin{enumerate}
  \item $p(1)-2p\!\left(\frac12\right)+2p\!\left(-\frac12\right)-p(-1)$ の値は $a,\ b,\ c$ によらない定数であることを示し，その値を求めよ．
  \item $-1\leqq x\leqq1$ をみたすすべての実数 $x$ に対して $|p(x)|\leqq\dfrac14$ が成り立つような $(a,b,c)$ をすべて求めよ．
  \item $-1\leqq x\leqq1$ における $|p(x)|$ の最大値を $M(a,b,c)$ とする．$M(a,b,c)$ の最小値を求めよ．
\end{enumerate}

実数 $a,\ b,\ c$ が $a+b+c=0,\ a^2+b^2+c^2=6$ をみたすとする．
\begin{enumerate}
  \item $a$ のとりうる値の範囲を求めよ．
  \item $abc$ のとりうる値の範囲を求めよ．
  \item $|a|+|b|+|c|$ のとりうる値の範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $(2x-1)^6$ の展開式における $x^4$ の係数を求めよ．
  \item $\left(x^2+\dfrac{1}{x}\right)^6$ の展開式における定数項を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $2x^3-3x^2+4x-5$ を $x^2-x+2$ で割った商と余りを求めよ．
  \item 整式 $A$ を $x^2+x-1$ で割ると，商が $2x-3$，余りが $x+4$ である．$A$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\dfrac{x+3}{x^2-1}-\dfrac{2}{x-1}$ を計算せよ．
  \item $\dfrac{1}{x(x+1)}+\dfrac{1}{(x+1)(x+2)}$ を計算せよ．
\end{enumerate}

\begin{enumerate}
  \item $\dfrac{1-\dfrac{1}{x}}{x-\dfrac{1}{x}}$ を簡単にせよ．
  \item $\dfrac{1}{1-\dfrac{1}{1-x}}$ を簡単にせよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$ のとき，$x+\dfrac{9}{x}$ の最小値と，そのときの $x$ の値を求めよ．
  \item $x>0$ のとき，$2x+\dfrac{1}{x}$ の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\dfrac{3+i}{1-2i}$ を $a+bi$（$a,\ b$ は実数）の形で表せ．
  \item $(2+i)^2(1-i)$ を $a+bi$（$a,\ b$ は実数）の形で表せ．
\end{enumerate}

\begin{enumerate}
  \item 2次方程式 $2x^2-4x+3=0$ の2つの解を $\alpha,\ \beta$ とする．$\alpha^2+\beta^2$ と $\alpha^3+\beta^3$ の値を求めよ．
  \item (1) の $\alpha,\ \beta$ について，$\dfrac{\beta}{\alpha}+\dfrac{\alpha}{\beta}$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 2数 $2+\sqrt3,\ 2-\sqrt3$ を解とする2次方程式を $x^2+px+q=0$ の形で求めよ．$p,\ q$ の値を答えよ．
  \item 2次方程式 $x^2-x+3=0$ の2つの解を $\alpha,\ \beta$ とする．$\alpha+1,\ \beta+1$ を解とする2次方程式を $x^2+px+q=0$ の形で求めよ．$p,\ q$ の値を答えよ．
\end{enumerate}

\begin{enumerate}
  \item 整式 $P(x)=x^3-2x^2+ax+3$ を $x-2$ で割った余りが $5$ であるとき，定数 $a$ の値を求めよ．
  \item (1) のとき，$P(x)$ を $x+1$ で割った余りを求めよ．
\end{enumerate}

$\dfrac{x}{2}=\dfrac{y}{3}=\dfrac{z}{4}\neq0$ のとき，次の式の値を求めよ．
\begin{enumerate}
  \item $\dfrac{x+y+z}{x-y+z}$
  \item $\dfrac{xy+yz+zx}{x^2+y^2+z^2}$
\end{enumerate}

\begin{enumerate}
  \item $(x+2y-z)^6$ の展開式における $x^2y^3z$ の係数を求めよ．
  \item $(1+2x-x^2)^4$ の展開式における $x^3$ の係数を求めよ．
\end{enumerate}

次の値を求めよ．
\begin{enumerate}
  \item ${}_6\mathrm{C}_0+{}_6\mathrm{C}_1\cdot3+{}_6\mathrm{C}_2\cdot3^2+\cdots+{}_6\mathrm{C}_6\cdot3^6$
  \item ${}_{10}\mathrm{C}_0+{}_{10}\mathrm{C}_2+{}_{10}\mathrm{C}_4+\cdots+{}_{10}\mathrm{C}_{10}$
  \item ${}_8\mathrm{C}_1+2\cdot{}_8\mathrm{C}_2+3\cdot{}_8\mathrm{C}_3+\cdots+8\cdot{}_8\mathrm{C}_8$
\end{enumerate}

\begin{enumerate}
  \item $x>1$ のとき，$x+\dfrac{4}{x-1}$ の最小値と，そのときの $x$ の値を求めよ．
  \item $a>0,\ b>0$ のとき，$\left(a+\dfrac1b\right)\left(b+\dfrac4a\right)$ の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x=1+\sqrt2\,i$ のとき，$x^2-2x$ の値を求めよ．
  \item $x=1+\sqrt2\,i$ のとき，$x^4-x^3+x^2+3x+1$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 2次方程式 $x^2+kx+8=0$ の2つの解の差が $2$ であるとき，定数 $k$ の値を求めよ．
  \item 2次方程式 $x^2-(k+1)x+2k=0$ の一方の解が他方の解の $2$ 倍であるとき，定数 $k$ の値を求めよ．
\end{enumerate}

2次方程式 $x^2-2kx+k+2=0$ について，次の条件を満たす定数 $k$ の値の範囲を求めよ．
\begin{enumerate}
  \item 異なる2つの正の解をもつ．
  \item 正の解と負の解を1つずつもつ．
\end{enumerate}

3次方程式 $x^3-2x^2+3x-4=0$ の3つの解を $\alpha,\ \beta,\ \gamma$ とする．次の値を求めよ．
\begin{enumerate}
  \item $\alpha^2+\beta^2+\gamma^2$
  \item $(1+\alpha)(1+\beta)(1+\gamma)$
  \item $\dfrac1\alpha+\dfrac1\beta+\dfrac1\gamma$
\end{enumerate}

\begin{enumerate}
  \item 3次方程式 $x^3+ax^2+bx+6=0$ が $1+i$ を解にもつとき，実数の定数 $a,\ b$ の値を求めよ．
  \item (1) のとき，この方程式の実数解を求めよ．
\end{enumerate}

方程式 $x^3=1$ の虚数解の1つを $\omega$ とする．次の値を求めよ．
\begin{enumerate}
  \item $\omega^{20}+\omega^{10}+1$
  \item $\dfrac{1}{1+\omega}+\dfrac{1}{1+\omega^2}$
  \item $(1-\omega)(1-\omega^2)$
\end{enumerate}

\begin{enumerate}
  \item $x^3+(k-1)x^2-k$ を因数分解せよ．
  \item 3次方程式 $x^3+(k-1)x^2-k=0$ の異なる実数解がちょうど2個となるような，定数 $k$ の値をすべて求めよ．
\end{enumerate}

$n$ を正の整数とし，$P(x)$ を実数を係数とする $n$ 次以上の整式とする．$P(x)$ の $x^j$ の係数を $c_j$（$j=0,1,2,\dots$）とする．ただし，定数項については項それ自身を係数とみなす．
\begin{enumerate}
  \item $(2+x)P(x)$ の $n$ 次以下の項の係数がすべて整数ならば，$j=0,1,\dots,n$ について $2^{j+1}c_j$ は整数であることを示せ．また，各 $n$ に対して，この仮定をみたし $2^nc_n$ が整数でない $P(x)$ の例を1つ挙げよ．
  \item $(2+x)P(x)$ と $(2+3x)P(x)$ の $n$ 次以下の項の係数がすべて整数ならば，$c_0,c_1,\dots,c_{n-2}$ はすべて整数であり（$n\geqq2$ のとき），$2c_{n-1}$，$4c_n$ も整数であることを示せ．
  \item (2) の仮定をみたし，$c_{n-1}$ も $2c_n$ も整数でない $P(x)$ の例を1つ挙げよ．
\end{enumerate}

0以上の整数 $n$ に対し，$x^n$ を $x^3-x^2-x-1$ で割った余りを $a_nx^2+b_nx+c_n$ とする．
\begin{enumerate}
  \item $a_{n+1}$，$b_{n+1}$，$c_{n+1}$ を $a_n$，$b_n$，$c_n$ を用いて表せ．
  \item すべての $n$ について，$a_n$，$b_n$，$c_n$ の3つをすべて割り切る正の整数は1だけであることを示せ．
  \item $a_n$ と $b_n$ がともに偶数となるような正の整数 $n$ をすべて求めよ．
\end{enumerate}

$a,b,c,d$ を正の数とし，$f(x)=x^2-(a+d)x+(ad-bc)$ とおく．
\begin{enumerate}
  \item 2次方程式 $f(x)=0$ は異なる2つの実数解をもち，大きい方の解 $\lambda$ は $\lambda>a$ かつ $\lambda>d$ をみたし，小さい方の解 $\mu$ は $|\mu|<\lambda$ をみたすことを示せ．
  \item 正の数 $x_1,y_1$ を与え，数列 $\{x_n\}$，$\{y_n\}$ を
  \[x_{n+1}=ax_n+cy_n,\qquad y_{n+1}=bx_n+dy_n\quad(n=1,2,\dots)\]
  で定める．次の3条件は互いに同値であることを示せ．
  \begin{itemize}
    \item[(i)] $s(1-a)-tb>0$ と $-sc+t(1-d)>0$ を同時にみたす正の数 $s,t$ が存在する．
    \item[(ii)] $\lambda<1$．
    \item[(iii)] $\displaystyle\lim_{n\to\infty}x_n=\lim_{n\to\infty}y_n=0$．
  \end{itemize}
\end{enumerate}

複素数 $\alpha$，$\beta$，$\gamma$，$\delta$ および実数 $a$，$b$ が，次の3条件をみたしながら動く．
\begin{itemize}
  \item[条件1：] $\alpha$，$\beta$，$\gamma$，$\delta$ は相異なる．
  \item[条件2：] $\alpha$，$\beta$，$\gamma$，$\delta$ は4次方程式 $z^4+az^3+bz^2+az+1=0$ の解である．
  \item[条件3：] 複素数 $\alpha+\beta$ の実部は0であり，虚部は0でない．
\end{itemize}
\begin{enumerate}
  \item $a\neq0$ ならば，$\alpha$，$\beta$，$\gamma$，$\delta$ のうちちょうど2つが実数であり，その2つの積は1であることを示せ．
  \item 点 $(a,b)$ の動く範囲を座標平面上に図示せよ．
  \item $a\neq0$ であるとき，$\alpha+\beta$ がとりうる値の範囲を求めよ．
\end{enumerate}

$k$ を実数とし，$x$ の2次方程式 $x^2+x-k=0$ の2つの解を $\alpha$，$\beta$ とする（重解のときは $\alpha=\beta$ とする）．ただし $k$ は，この方程式が実数解をもち，かつ $x=1$ を解にもたないような範囲を動くものとし，
\[
E(k)=\frac{\alpha^3}{1-\beta}+\frac{\beta^3}{1-\alpha}
\]
とおく．
\begin{enumerate}
  \item $k$ のとりうる値の範囲を求め，$E(k)$ を $k$ の式で表せ．
  \item 実数 $m$ に対し，$E(k)=m$ をみたす $k$ の個数を求めよ．
\end{enumerate}

整式 $f(x)=(x-1)^2(x-2)$ を考える．
\begin{enumerate}
  \item $g(x)$，$P(x)$ を実数を係数とする整式とし，$g(x)$ を $f(x)$ で割った余りを $r(x)$ とする．$P(g(x))$ を $f(x)$ で割った余りと $P(r(x))$ を $f(x)$ で割った余りが等しいことを示せ．
  \item $a$，$b$ を実数とし，$h(x)=x^2+ax+b$ とおく．$h(h(x))$ を $f(x)$ で割った余りを $h_1(x)$ とし，$h(h_1(x))$ を $f(x)$ で割った余りを $h_2(x)$ とする．$h_2(x)$ が $h_1(x)$ に等しくなるような $a$，$b$ の組をすべて求めよ．
\end{enumerate}

$n$ を自然数とし，整式 $x^n$ を整式 $x^2-2x-1$ で割った余りを $a_nx+b_n$ とする．
\begin{enumerate}
  \item $a_n,b_n$ は整数であることを示し，$a_{2n},\ b_{2n}$ を $a_n,\ b_n$ で表せ．
  \item すべての $n$ に対して $a_n+b_n$ は奇数であることを示せ．
  \item $a_n$ が $2^{10}$ で割り切れるような $n$ をすべて求めよ．
\end{enumerate}

$c=\sqrt[3]2$，$\alpha=c+c^2=\sqrt[3]2+\sqrt[3]4$ とする．
\begin{enumerate}
  \item $\alpha$ を解にもつ整数係数の3次方程式 $x^3+sx+t=0$ を1つ求めよ．
  \item 有理数 $u,v,w$ が $u+vc+wc^2=0$ をみたすならば $u=v=w=0$ であることを示せ．ただし $c$ が無理数であることも証明すること．
  \item $P(x)$ は有理数を係数とする $x$ の多項式で $P(\alpha)=0$ をみたすとする．このとき $P(x)$ は (1) で求めた3次式 $x^3+sx+t$ で割り切れることを証明せよ．
\end{enumerate}

$a,b$ を互いに素な正の整数，$n$ を正の整数とし，$i$ を虚数単位とする．
\begin{enumerate}
  \item $(a+bi)^n$ が実数となるような $(a,b,n)$ をすべて求めよ．
  \item $(a+bi)^n$ が純虚数となるような $(a,b,n)$ をすべて求めよ．
\end{enumerate}

$a$，$b$，$c$ を実数とする．$y=x^3+3ax^2+3bx$ と $y=c$ のグラフが相異なる3つの交点をもち，それらの $x$ 座標を $\alpha<\beta<\gamma$ とする．
\begin{enumerate}
  \item $a^2>b$ が成り立つことを示せ．
  \item $a$，$b$ を固定し，$c$ を（3つの交点をもつ範囲で）動かすとき，$\gamma-\alpha$ のとりうる値の範囲を $a$，$b$ で表せ．
  \item 同様に，$\beta$ のとりうる値の範囲を $a$，$b$ で表せ．
\end{enumerate}

複素数を係数とする3次式 $f(x)=x^3+ax^2+bx+c$ について，次の2つの条件を考える．
\begin{enumerate}
  \item[(イ)] $f(x^2)$ は $f(x)$ で割り切れる．
  \item[(ロ)] $a,b,c$ の少なくとも1つは虚数である．
\end{enumerate}
(イ)，(ロ) を同時にみたす3次式 $f(x)$ をすべて求めよ．

$Q(x)$ を実数係数の2次式とする．
\begin{enumerate}
  \item 実数係数の整式 $P(x)$ で，$P(x)$ は $Q(x)$ で割り切れないが，$P(x)P(-x)$ は $Q(x)$ で割り切れるようなものが存在するための $Q(x)$ の条件を求めよ．
  \item $Q(x)=x^2+x+1$ のとき，(1) の条件をみたす $P(x)$ のうち次数が最小のものをすべて求めよ．
\end{enumerate}

正の整数 $n$ に対して $F_n(x)=(x^n+1)^n+(x^2+1)^n+1$ とおく．
\begin{enumerate}
  \item $F_n(x)$ を $x^2+x+1$ で割った余りを，$n$ を6で割った余りで分類して求めよ．
  \item $F_n(x)$ が $x^2+x+1$ で割り切れるような $n$ を求めよ．また，そのような $n$ に対して $F_n(x)$ は $(x^2+x+1)^2$ では割り切れないことを示せ．
\end{enumerate}

実数 $a$ は $0<a\leqq2$ の範囲を動くものとする．
\begin{enumerate}
  \item $y=\sqrt x$ と $y=\dfrac2ax+1-\dfrac1a$ のグラフの共有点の個数を，$a$ の値によって分類せよ．
  \item 2次方程式 $(2x+a-1)^2=a^2x$ の複素数の範囲で考えた2つの解を $\alpha,\beta$ とする．$|\alpha|+|\beta|$ の最小値と，$|\alpha-\beta|$ の最大値を求めよ．
\end{enumerate}

$a,b,c$ を整数とし，$x$ の3次方程式
\[
x^3+ax^2+bx+c=0\quad\cdots\text{①}
\]
は虚数解 $\alpha$ をもち，さらに $\alpha^3$ も①の解であるとする．
\begin{enumerate}
  \item $|\alpha|=2$ となる場合の $\alpha$ としてありうる値をすべて求めよ．
  \item $|c|\leqq100$ をみたす整数の組 $(a,b,c)$ は何組あるか．
\end{enumerate}

さいころの $k$ の目が出る確率を $p_k$（$k=1,2,\dots,6$）とする．ただし $p_k\geqq0$，$p_1+p_2+\cdots+p_6=1$ である．このさいころを3回投げる．$S_2=\displaystyle\sum_{k=1}^6p_k^2$，$S_3=\displaystyle\sum_{k=1}^6p_k^3$ とおく．
\begin{enumerate}
  \item 3回とも同じ目が出る確率 $A$，3回の目がすべて異なる確率 $B$ を，それぞれ $S_2,S_3$ で表せ．
  \item $A\geqq\dfrac1{36}$ を示せ．また，等号が成り立つ条件を求めよ．
  \item 3回のうち少なくとも2回同じ目が出る確率は $\dfrac49$ 以上であることを示せ．また，等号が成り立つ条件を求めよ．
\end{enumerate}

$x_1,x_2,x_3,x_4$ を正の実数，$t$ を正の定数とし，
\[
F=\frac{x_1}{x_2+tx_3}+\frac{x_2}{x_3+tx_4}+\frac{x_3}{x_4+tx_1}+\frac{x_4}{x_1+tx_2}
\]
とおく．
\begin{enumerate}
  \item $t=1$ のとき $F\geqq2$ を示し，等号が成り立つための $x_1,x_2,x_3,x_4$ の条件を求めよ．
  \item $0<t<1$ のとき，$F$ の最小値と，最小値をとるための条件を求めよ．
  \item $t>1$ のとき，つねに $F>\dfrac2t$ であることを示せ．また，どんな正の数 $\delta$ に対しても $F<\dfrac2t+\delta$ となる $x_1,x_2,x_3,x_4$ が存在することを示せ．
\end{enumerate}
